var t=`0020-salo-with-garlic`;var a=`world-0020`;var r=`UA`;var n=`eastern-europe`;var l=4;var s=16;var o={en:`Salo with Garlic`,ua:`Сало з часником`};var d={en:`A classic dish from Ukraine, featuring salo (salt-cured pork fat), garlic, rye bread. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: сало солоне, часник, житній хліб. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var c=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:3,i:[[`salo-salt-cured-pork-fat`,250,`g`],[`garlic`,4,`clove`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:3,i:[[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Chill briefly if appropriate, garnish with the listed ingredients and serve at the intended temperature.`,ua:`За потреби недовго охолодіть, прикрасьте зазначеними складниками й подавайте за потрібної температури.`,t:[`garnishing`],m:10,i:[[`rye-bread`,200,`g`]]}];var g={slug:t,id:a,country:`UA`,region:n,servings:4,minutes:16,title:o,text:d,steps:c};export{r as country,g as default,a as id,s as minutes,n as region,l as servings,t as slug,c as steps,d as text,o as title};